    function updateProgress() {
      if (!currentStats) return;
      const now = Date.now();
      const last = new Date(currentStats.last_wake).getTime();
      const elapsed = Math.floor((now - last) / 1000);
      const remaining = Math.max(0, 5400 - elapsed);
      const progress = Math.min(elapsed, 5400) * 100 / 5400;
      els.wakeProgress.value = Math.min(elapsed, 5400);
      if (elapsed >= 5400) {
        els.wakeProgressText.textContent = "Wake window full — waiting for next trigger";
      } else {
        const remainingMinutes = Math.floor(remaining / 60);
        if (remainingMinutes > 0) {
          els.wakeProgressText.textContent = remainingMinutes + " minute" + (remainingMinutes === 1 ? "" : "s") + " remaining";
        } else {
          els.wakeProgressText.textContent = "Less than a minute remaining";
        }
      }
    }

    // Initial load
    updateHomepageData().then(function () {
      initUpdatesPage();
      // Start real-time progress updates (every second)
      setInterval(updateProgress, 1000);
    });

    // Refresh button handler
    if (els.refreshBtn) {
      els.refreshBtn.addEventListener("click", function () {
        els.refreshBtn.disabled = true;
        els.refreshBtn.textContent = "🔄 Refreshing...";
        updateHomepageData()
          .finally(function () {
            els.refreshBtn.disabled = false;
            els.refreshBtn.textContent = "🔄 Refresh";
          });
      });
    }
  }

